INSERT INTO public.aquarium_notes VALUES (1, 'Marcelo (Bamba Aqua)', 'Realizada checagem visual dos corais duros. Acropora millepora apresentando crescimento nas pontas. Skimmer limpo e regulado.', '2026-10-10 23:34:02.978825', '2026-10-10 23:34:02.978825', 'Avaliação Periódica do Reef', 1);
INSERT INTO public.aquarium_notes VALUES (2, 'Atendente Balcão', 'Cliente adquiriu dosadora Jebao 4 canais. Programada para dosar Kh, Cálcio e Magnésio de hora em hora.', '2026-09-24 23:34:02.978825', '2026-09-24 23:34:02.978825', 'Instalação de Bomba Dosadora', 1);
INSERT INTO public.aquarium_notes VALUES (3, 'Marcelo (Bamba Aqua)', 'Poda das Rotalas e replantio das mudas. Inseridas pastilhas de NPK no substrato próximo às raízes das espadas amazônicas.', '2026-10-07 23:34:02.978825', '2026-10-07 23:34:02.978825', 'Poda Geral e Adubação', 3);
INSERT INTO public.aquarium_notes VALUES (4, 'Atendente Balcão', 'Cliente trouxe o refratômetro para aferição na loja. Calibrado com líquido de referência 35ppt.', '2026-10-05 23:34:02.978825', '2026-10-05 23:34:02.978825', 'Calibração de Refratômetro Óptico', 4);
INSERT INTO public.aquarium_notes VALUES (5, 'Marcelo (Bamba Aqua)', 'Realizado banho profilático com dip coral antes da colagem na rocha matriz.', '2026-10-03 23:34:02.978825', '2026-10-03 23:34:02.978825', 'Aclimatação de Coral Torch Gold', 5);
INSERT INTO public.aquarium_notes VALUES (6, 'Lucas Ferraz', 'Realizada TPA de 25% com água tratada com Prime e adicionadas 2 folhas secas de catappa para liberar taninos benéficos.', '2026-09-30 23:34:02.978825', '2026-09-30 23:34:02.978825', 'Troca Parcial e Adição de Folhas de Amendoeira', 6);
INSERT INTO public.aquariums VALUES (1, '2026-08-13 23:34:02.975416', 'Aquário marinho misto com corais SPS (Acroporas) e LPS (Torches), substrato de aragonita viva e sump de 100L com skimmer potente.', 'Reef dos Sonhos 350L', 'MARINE', 350, 1);
INSERT INTO public.aquariums VALUES (2, '2026-09-02 23:34:02.975416', 'Aquário hospital e quarentena para aclimatação segura de novos peixes antes da entrada no aquário principal.', 'Nano Quarentena 50L', 'MARINE', 50, 1);
INSERT INTO public.aquariums VALUES (3, '2026-08-23 23:34:02.975416', 'Aquário plantado densamente povoado com CO2 pressurizado, substrato fértil Amazônia, cardume de Neons e casal de Acarás Disco.', 'Plantado Amazônico High-Tech', 'FRESHWATER', 240, 2);
INSERT INTO public.aquariums VALUES (4, '2026-08-28 23:34:02.975416', 'Aquário marinho focado em cirurgiões (Yellow Tang, Blue Tang), corais moles e colônias gigantes de Zoanthus.', 'Reef Marinho 500L', 'MARINE', 500, 3);
INSERT INTO public.aquariums VALUES (5, '2026-09-07 23:34:02.975416', 'Aquário de corais focado em Euphyllias (Hammer, Frogspawn, Torch) com iluminação LED espectro azul actinico.', 'Nano Coral Garden 80L', 'MARINE', 80, 4);
INSERT INTO public.aquariums VALUES (6, '2026-09-17 23:34:02.975416', 'Aquário com troncos tratados, folhas de amendoeira, plantas low-tech (Microsorum e Anubias) e Betta Halfmoon.', 'Biótopo Asiático Betta & Corys', 'FRESHWATER', 90, 5);
INSERT INTO public.aquariums VALUES (7, '2026-09-22 23:34:02.975416', 'Aquário marinho temático com rochas vivas abrigando Peixe-leão e moreia.', 'Reef Predadores 400L', 'MARINE', 400, 6);
