INSERT INTO public.water_parameter_tests VALUES (1, 0, 430, 'Corais expandindo pólipos com vitalidade máxima. Peixes ativos e comendo com voracidade.', '2026-10-10 23:34:02.977086', 'Parâmetros ideais para corais SPS e LPS. Relação nitrato/fosfato equilibrada (Redfield). Manter a rotina de dosagem do Balling e TPA quinzenal com água deionizada.', NULL, 8.5, 1380, 5, 0, 8.3, 0.03, 1.025, 0, 25.5, '2026-10-10 23:34:02.977086', 1);
INSERT INTO public.water_parameter_tests VALUES (2, 0, 410, 'Surgimento discreto de diatomáceas e algas filamentosas no vidro traseiro.', '2026-09-22 23:34:02.977086', 'Fosfato e nitrato acima do nível de segurança. Orientada troca do refil de carvão ativado e adição temporária de resina removedora de fosfato.', NULL, 7.8, 1310, 18, 0, 8.1, 0.1, 1.024, 0.1, 26, '2026-09-22 23:34:02.977086', 1);
INSERT INTO public.water_parameter_tests VALUES (3, 0, NULL, 'Plantas fazendo pearling intenso à tarde. Discos nadando tranquilos.', '2026-10-08 23:34:02.977086', 'Água doce ácida e mole ideal para peixes amazônicos e absorção de micronutrientes pelas plantas. Manter fertilização de ferro e potássio.', 5, 3, NULL, 10, 0, 6.6, 0.6, NULL, NULL, 28, '2026-10-08 23:34:02.977086', 3);
INSERT INTO public.water_parameter_tests VALUES (4, 0.03, 450, 'Água um pouco opaca após introdução de nova rocha e peixe.', '2026-10-06 23:34:02.977086', 'Leve pico de amônia e salinidade um pouco alta (1.027). Recomenda-se reposição de 15L com água doce RO/DI para baixar densidade para 1.025 e aplicação de bio-bactérias.', NULL, 9.2, 1400, 25, 0, 8.1, 0.15, 1.027, NULL, 25.8, '2026-10-06 23:34:02.977086', 4);
INSERT INTO public.water_parameter_tests VALUES (5, 0, 420, 'Torches e hammers com coloração viva e abrindo completamente.', '2026-10-04 23:34:02.977086', 'Equilíbrio iônico e alcalinidade estáveis. Nenhum ajuste corretivo necessário.', NULL, 8, 1340, 8, 0, 8.2, 0.04, 1.025, 0, 25.2, '2026-10-04 23:34:02.977086', 5);
INSERT INTO public.water_parameter_tests VALUES (6, 0, NULL, 'Betta muito ativo construindo ninho de bolhas na superfície.', '2026-10-02 23:34:02.977086', 'Condições da água neutra e límpida com taninos adequados. Excelente saúde do exemplar.', 6, 4, NULL, 5, 0, 7, 0.2, NULL, NULL, 26.5, '2026-10-02 23:34:02.977086', 6);
